<template><section><div class="page-header"><div><p class="eyebrow">Operations</p><h1>Bookings</h1><p class="lede">Review appointment requests and keep their next step explicit.</p></div><div class="filters"><label class="sr-only" for="status">Filter by status</label><select id="status" v-model="status"><option value="all">All statuses</option><option value="pending">Pending</option><option value="confirmed">Confirmed</option><option value="cancelled">Cancelled</option></select><input v-model="date" type="date" aria-label="Filter by date" /></div></div><div v-if="workspace.bookings.length" class="booking-list"><article v-for="booking in filtered" :key="booking.id" class="card booking-row"><div><span class="status-chip" :class="booking.status">{{ booking.status }}</span><h2>{{ booking.customer }}</h2><p class="muted">{{ booking.service }} · {{ booking.starts }}</p></div><button class="button" type="button" @click="selected=booking">View details</button></article><div v-if="!filtered.length" class="empty"><h2>No matching bookings</h2><p>Try a different status or date.</p></div></div><div v-else class="empty"><h2>No bookings yet</h2><p>Guest requests will appear here once your booking flow is connected to this workspace.</p></div><div v-if="selected" class="drawer-backdrop" @click.self="selected=null"><aside class="drawer" aria-label="Booking details"><button class="close" type="button" @click="selected=null" aria-label="Close details">×</button><p class="eyebrow">Booking detail</p><h2>{{ selected.customer }}</h2><p class="muted">{{ selected.service }} · {{ selected.starts }}</p><div class="detail-block"><strong>Status</strong><span class="status-chip" :class="selected.status">{{ selected.status }}</span></div><div class="form-actions"><button class="button button-primary" :disabled="selected.status==='confirmed'" @click="changeStatus('confirmed')">Confirm</button><button class="button" :disabled="selected.status==='cancelled'" @click="changeStatus('cancelled')">Cancel</button><button class="button" @click="changeStatus('pending')">Mark pending</button></div><p v-if="detailNotice" class="success" role="status">{{ detailNotice }}</p></aside></div></section></template>
<script setup>import { computed, inject, ref } from 'vue'; const workspace=inject('workspace'),status=ref('all'),date=ref(''),selected=ref(null),detailNotice=ref(''); const filtered=computed(()=>workspace.bookings.filter(b=>(status.value==='all'||b.status===status.value)&&(!date.value||b.starts.startsWith(date.value)))); function changeStatus(next){selected.value.status=next;detailNotice.value='Booking updated.';setTimeout(()=>detailNotice.value='',2200)}</script>
<style scoped>.filters{display:flex;gap:8px}.filters select,.filters input{width:auto;min-width:145px}.booking-list{display:grid;gap:14px}.booking-row{display:flex;justify-content:space-between;align-items:center;gap:18px}.booking-row h2{margin:10px 0 5px}.status-chip{display:inline-block;padding:6px 9px;border-radius:5px;background:#edf0f4;color:#4d5967;font-size:12px;font-weight:800;text-transform:capitalize}.status-chip.confirmed{background:#e7f5ed;color:#176b45}.status-chip.pending{background:#fff5d9;color:#765600}.status-chip.cancelled{background:#fff0ef;color:var(--danger)}.drawer-backdrop{position:fixed;inset:0;z-index:5;background:rgba(23,32,42,.4)}.drawer{position:absolute;right:0;top:0;height:100%;width:min(440px,100%);padding:38px 28px;background:#fff;box-shadow:-12px 0 30px rgba(23,32,42,.12)}.close{position:absolute;right:18px;top:15px;border:0;background:transparent;font-size:27px;min-height:44px}.detail-block{display:flex;justify-content:space-between;align-items:center;padding:20px 0;margin:24px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}@media(max-width:600px){.filters{width:100%;flex-wrap:wrap}.filters select,.filters input{flex:1;min-width:0}.booking-row{align-items:flex-start;flex-direction:column}}</style>